codeExamples.code:
// Works! Function declarations are hoisted
sayHello();  // "Hello!"

function sayHello() {
  console.log("Hello!");
}

// Does NOT work: let/const are in TDZ
// console.log(x);  // ReferenceError!
let x = 5;

// Global context
let globalVar = "I'm global";

function outer() {
  let outerVar = "I'm in outer";

  function inner() {
    let innerVar = "I'm in inner";
    console.log(globalVar);  // ✓ accessible
    console.log(outerVar);   // ✓ accessible
    console.log(innerVar);   // ✓ accessible
  }

  inner();
  // inner's context is destroyed after this line
}

outer();
// outer's context is destroyed after this line

function first() {
  console.log("first start");
  second();
  console.log("first end");
}

function second() {
  console.log("second start");
  third();
  console.log("second end");
}

function third() {
  console.log("third");
}

first();
// Output:
// first start
// second start
// third
// second end
// first end

// ❌ Infinite recursion — causes stack overflow
function countDown(n) {
  console.log(n);
  countDown(n - 1);  // no stopping condition!
}
// countDown(5);  // RangeError!

// ✅ Correct: with a base case
function countDownSafe(n) {
  if (n <= 0) return;  // base case stops recursion
  console.log(n);
  countDownSafe(n - 1);
}
countDownSafe(5);  // 5, 4, 3, 2, 1
